'use strict';

var Int64 = require( '@stdlib/number/int64/ctor' );
var add = require( './../lib' );

// Addition beyond JavaScript's safe integer limit (10^18 > 2^53 - 1):
var a = new Int64( 1e18 );
var b = new Int64( 1 );
var v = add( a, b );
console.log( '%s + %s = %s', a, b, v );
// => '1000000000000000000 + 1 = 1000000000000000001'

a = new Int64( -1e18 );
b = new Int64( -1 );
v = add( a, b );
console.log( '%s + %s = %s', a, b, v );
// => '-1000000000000000000 + -1 = -1000000000000000001'

a = new Int64( 1e18 );
b = new Int64( -1 );
v = add( a, b );
console.log( '%s + %s = %s', a, b, v );
// => '1000000000000000000 + -1 = 999999999999999999'

// Signed two's complement overflow wrap-around (INT64_MAX + 1 = INT64_MIN):
a = Int64.of( 0x7fffffff, 0xffffffff );
b = new Int64( 1 );
v = add( a, b );
console.log( '%s + %s = %s', a, b, v );
// => '9223372036854775807 + 1 = -9223372036854775808'
